import unittest
import limiter
import window


class TestRateLimiter(unittest.TestCase):

    def test_window_empty_count(self):
        w = window.Window(10.0)
        self.assertEqual(w.count_since(5.0), 0)

    def test_window_add_and_count_within_length(self):
        w = window.Window(10.0)
        w.add(1.0)
        w.add(3.0)
        self.assertEqual(w.count_since(5.0), 2)

    def test_window_count_expires_old_entries(self):
        w = window.Window(5.0)
        w.add(1.0)
        w.add(2.0)
        w.add(8.0)
        self.assertEqual(w.count_since(10.0), 1)

    def test_window_all_expired(self):
        w = window.Window(2.0)
        w.add(1.0)
        w.add(1.5)
        self.assertEqual(w.count_since(10.0), 0)

    def test_window_invalid_length_zero(self):
        with self.assertRaises(ValueError):
            window.Window(0.0)

    def test_window_invalid_length_negative(self):
        with self.assertRaises(ValueError):
            window.Window(-1.0)

    def test_simulate_empty_times(self):
        self.assertEqual(limiter.simulate([], 3, 10.0), [])

    def test_simulate_all_within_limit(self):
        res = limiter.simulate([1.0, 2.0, 3.0], 3, 10.0)
        if res and isinstance(res[0], bool):
            self.assertEqual(res, [True, True, True])
        else:
            self.assertEqual(res, [1.0, 2.0, 3.0])

    def test_simulate_exceeds_limit_in_window(self):
        res = limiter.simulate([1.0, 2.0, 3.0, 4.0], 2, 10.0)
        if res and isinstance(res[0], bool):
            self.assertEqual(res, [True, True, False, False])
        else:
            self.assertEqual(res, [1.0, 2.0])

    def test_simulate_allows_after_window_slides(self):
        res = limiter.simulate([1.0, 2.0, 3.0, 15.0], 2, 5.0)
        if res and isinstance(res[0], bool):
            self.assertEqual(res, [True, True, False, True])
        else:
            self.assertEqual(res, [1.0, 2.0, 15.0])

    def test_simulate_single_limit(self):
        res = limiter.simulate([1.0, 2.0, 10.0], 1, 5.0)
        if res and isinstance(res[0], bool):
            self.assertEqual(res, [True, False, True])
        else:
            self.assertEqual(res, [1.0, 10.0])

    def test_simulate_invalid_limit_zero(self):
        with self.assertRaises(ValueError):
            limiter.simulate([1.0], 0, 5.0)

    def test_simulate_invalid_limit_negative(self):
        with self.assertRaises(ValueError):
            limiter.simulate([1.0], -2, 5.0)

    def test_simulate_invalid_length_zero(self):
        with self.assertRaises(ValueError):
            limiter.simulate([1.0], 2, 0.0)

    def test_simulate_invalid_length_negative(self):
        with self.assertRaises(ValueError):
            limiter.simulate([1.0], 2, -5.0)


if __name__ == "__main__":
    unittest.main()

