import unittest
from textwrap2 import wrap_words


class TestWrapWords(unittest.TestCase):
    def test_empty_text_returns_empty_list(self):
        self.assertEqual(wrap_words("", 10), [])

    def test_all_whitespace_text_returns_empty_list(self):
        self.assertEqual(wrap_words("   \t\n  \r ", 5), [])

    def test_single_word_shorter_than_width(self):
        self.assertEqual(wrap_words("hello", 10), ["hello"])

    def test_single_word_exact_width(self):
        self.assertEqual(wrap_words("hello", 5), ["hello"])

    def test_width_equal_to_one_single_char_words(self):
        self.assertEqual(wrap_words("a b c", 1), ["a", "b", "c"])

    def test_width_equal_to_one_splits_multi_char_word(self):
        self.assertEqual(wrap_words("abc", 1), ["a", "b", "c"])

    def test_leading_and_trailing_whitespace_ignored(self):
        self.assertEqual(wrap_words("   hello world   ", 20), ["hello world"])

    def test_multiple_whitespace_collapsed_to_single_space(self):
        self.assertEqual(wrap_words("one   \t\n  two    three", 20), ["one two three"])

    def test_greedy_packing_fits_exact_width(self):
        # "ab cd" has length 5; "ef" wraps to next line
        self.assertEqual(wrap_words("ab cd ef", 5), ["ab cd", "ef"])

    def test_greedy_packing_one_over_width_wraps(self):
        # "ab cde" has length 6 > 5, so "cde" must go to next line
        self.assertEqual(wrap_words("ab cde", 5), ["ab", "cde"])

    def test_greedy_packing_multiple_lines(self):
        text = "the quick brown fox jumps over the lazy dog"
        expected = [
            "the quick",
            "brown fox",
            "jumps over",
            "the lazy",
            "dog",
        ]
        self.assertEqual(wrap_words(text, 10), expected)

    def test_long_word_split_exact_multiple_of_width(self):
        self.assertEqual(wrap_words("abcdefgh", 4), ["abcd", "efgh"])

    def test_long_word_split_with_shorter_last_piece(self):
        self.assertEqual(wrap_words("abcdefghij", 4), ["abcd", "efgh", "ij"])

    def test_long_word_last_piece_joins_with_next_word(self):
        # "abcdef" -> "abcd", "ef"; "ef" + " " + "g" = "ef g" (length 4 <= 4)
        self.assertEqual(wrap_words("abcdef g", 4), ["abcd", "ef g"])

    def test_word_before_long_word_cannot_fit_first_piece(self):
        # "a" is 1 char; first piece of "bcdefg" is "bcde" (4 chars).
        # "a bcde" is 6 > 4, so "a" is on its own line, then "bcde", then "fg".
        self.assertEqual(wrap_words("a bcdefg", 4), ["a", "bcde", "fg"])

    def test_multiple_long_words_and_normal_words(self):
        # "abcdef" -> "abc", "def"
        # "ghijklm" -> "ghi", "jkl", "m"
        # "n" -> joins with "m" to form "m n" (length 3 <= 3)
        self.assertEqual(
            wrap_words("abcdef ghijklm n", 3),
            ["abc", "def", "ghi", "jkl", "m n"],
        )

    def test_width_zero_raises_value_error(self):
        with self.assertRaises(ValueError):
            wrap_words("hello", 0)

    def test_width_negative_raises_value_error(self):
        with self.assertRaises(ValueError):
            wrap_words("hello", -1)
        with self.assertRaises(ValueError):
            wrap_words("hello", -100)

    def test_width_less_than_one_with_empty_text_raises_value_error(self):
        with self.assertRaises(ValueError):
            wrap_words("", 0)
        with self.assertRaises(ValueError):
            wrap_words("   ", -5)


if __name__ == "__main__":
    unittest.main()

