        for month in (1, 3, 5, 7, 8, 10, 12):
            with self.subTest(month=month):
                self.assertEqual(calendar2.days_in_month(2024, month), 31)

    def test_30_day_months_common_year(self):
        for month in (4, 6, 9, 11):
            with self.subTest(month=month):
                self.assertEqual(calendar2.days_in_month(2023, month), 30)

    def test_30_day_months_leap_year(self):
        for month in (4, 6, 9, 11):
            with self.subTest(month=month):
                self.assertEqual(calendar2.days_in_month(2024, month), 30)

    def test_february_common_year_not_divisible_by_4(self):
        for year in (1, 2, 3, 2023):
            with self.subTest(year=year):
                self.assertEqual(calendar2.days_in_month(year, 2), 28)

    def test_february_leap_year_divisible_by_4_not_100(self):
        for year in (4, 8, 1996, 2004, 2024):
            with self.subTest(year=year):
                self.assertEqual(calendar2.days_in_month(year, 2), 29)

