        for b in (True, False):
            with self.subTest(year=b):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(b, 1)

    def test_month_as_bool_raises_value_error(self):
        for b in (True, False):
            with self.subTest(month=b):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(2023, b)

    def test_both_args_as_bool_raises_value_error(self):
        with self.assertRaises(ValueError):
            calendar2.days_in_month(True, True)

    def test_non_int_year_raises_value_error(self):
        for bad_year in (2024.0, "2024", None, [2024], (2024,)):
            with self.subTest(year=bad_year):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(bad_year, 1)

    def test_non_int_month_raises_value_error(self):
        for bad_month in (1.0, "1", None, [1], (1,)):
            with self.subTest(month=bad_month):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(2024, bad_month)


if __name__ == "__main__":
