import unittest
import loader
import settings


class TestLoadSettings(unittest.TestCase):
    def test_empty_overrides_returns_copy_of_defaults(self):
        snapshot = dict(settings.DEFAULTS)
        result = loader.load_settings({})
        self.assertEqual(result, snapshot)
        self.assertIsNot(result, settings.DEFAULTS)

    def test_returned_dict_mutation_does_not_modify_defaults(self):
        snapshot = dict(settings.DEFAULTS)
        result = loader.load_settings({})
        result["port"] = 12345
        self.assertEqual(settings.DEFAULTS, snapshot)

    def test_valid_overrides_do_not_modify_defaults(self):
        snapshot = dict(settings.DEFAULTS)
        overrides = {"port": 8080, "workers": 4}
        result = loader.load_settings(overrides)
        self.assertEqual(settings.DEFAULTS, snapshot)
        expected = dict(snapshot)
        expected.update(overrides)
        self.assertEqual(result, expected)

    def test_valid_all_keys_updated(self):
        snapshot = dict(settings.DEFAULTS)
        overrides = {}
        for k, v in snapshot.items():
            if k == "port":
                overrides[k] = 9000
            elif k == "workers":
                overrides[k] = 8
            elif isinstance(v, bool):
                overrides[k] = not v
            elif isinstance(v, int):
                overrides[k] = v + 1
            elif isinstance(v, str):
                overrides[k] = v + "_custom"
            elif isinstance(v, float):
                overrides[k] = v + 1.0
        result = loader.load_settings(overrides)
        expected = dict(snapshot)
        expected.update(overrides)
        self.assertEqual(result, expected)
        self.assertEqual(settings.DEFAULTS, snapshot)

    def test_unknown_key_raises_value_error(self):
        snapshot = dict(settings.DEFAULTS)
        with self.assertRaises(ValueError):
            loader.load_settings({"__nonexistent_key__": 1})
        self.assertEqual(settings.DEFAULTS, snapshot)

    def test_unknown_key_mixed_with_valid_key_raises_value_error(self):
        snapshot = dict(settings.DEFAULTS)
        with self.assertRaises(ValueError):
            loader.load_settings({"port": 8080, "__unknown__": 1})
        self.assertEqual(settings.DEFAULTS, snapshot)

    def test_wrong_type_for_each_setting_raises_value_error(self):
        for k, v in settings.DEFAULTS.items():
            if isinstance(v, bool):
                bad_values = [1, 0, "true", None, [True]]
            elif isinstance(v, int):
                bad_values = [True, False, "123", 1.5, None, [1]]
            elif isinstance(v, str):
                bad_values = [123, True, None, ["a"]]
            elif isinstance(v, float):
                bad_values = [1, True, "1.0", None]
            else:
                bad_values = [object()]
            for bad in bad_values:
                with self.subTest(key=k, bad=bad):
                    with self.assertRaises(ValueError):
                        loader.load_settings({k: bad})

    def test_bool_rejected_for_port_and_workers(self):
        for key in ("port", "workers"):
            for val in (True, False):
                with self.subTest(key=key, val=val):
                    with self.assertRaises(ValueError):
                        loader.load_settings({key: val})

    def test_port_boundary_valid_values(self):
        for valid_port in (1, 80, 65535):
            with self.subTest(port=valid_port):
                result = loader.load_settings({"port": valid_port})
                self.assertEqual(result["port"], valid_port)

    def test_port_out_of_range_raises_value_error(self):
        for invalid_port in (-100, -1, 0, 65536, 70000):
            with self.subTest(port=invalid_port):
                with self.assertRaises(ValueError):
                    loader.load_settings({"port": invalid_port})

    def test_workers_boundary_valid_values(self):
        for valid_workers in (1, 2, 100):
            with self.subTest(workers=valid_workers):
                result = loader.load_settings({"workers": valid_workers})
                self.assertEqual(result["workers"], valid_workers)

    def test_workers_out_of_range_raises_value_error(self):
        for invalid_workers in (-10, -1, 0):
            with self.subTest(workers=invalid_workers):
                with self.assertRaises(ValueError):
                    loader.load_settings({"workers": invalid_workers})

