import unittest
import loader
import settings


def _get_defaults():
    for mod in (loader, settings):
        if hasattr(mod, "DEFAULTS"):
            return getattr(mod, "DEFAULTS")
    raise RuntimeError("DEFAULTS not found in loader or settings")


def _alternate_value(val):
    t = type(val)
    if t is bool:
        return not val
    if t is int:
        return val + 1 if val < 1000 else val - 1
    if t is float:
        return val + 1.5
    if t is str:
        return val + "_override"
    if t is list:
        return val + ["_item"]
    if t is dict:
        return {**val, "_k": "_v"}
    if t is tuple:
        return val + ("_item",)
    if t is set:
        return val | {"_item"}
    return val


def _wrong_type_values(val):
    t = type(val)
    if t is bool:
        return [1, 0, "true", None, [True]]
    if t is int:
        return [True, False, "10", 1.5, None]
    if t is float:
        return ["1.5", True, False, 1, None]
    if t is str:
        return [123, True, None, ["a"]]
    if t is list:
        return [("a",), "list", 123, None]
    if t is dict:
        return [[], "dict", 123, None]
    return [object()]


class TestLoadSettings(unittest.TestCase):
    def test_empty_overrides_returns_new_dict_equal_to_defaults(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        result = loader.load_settings({})
        self.assertEqual(result, snapshot)
        self.assertIsNot(result, defaults)
        self.assertEqual(defaults, snapshot)

    def test_valid_overrides_applied_and_defaults_unmodified(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        overrides = {}
        for k, v in snapshot.items():
            if k == "port":
                overrides[k] = 8080 if v != 8080 else 9090
            elif k == "workers":
                overrides[k] = 4 if v != 4 else 2
            else:
                overrides[k] = _alternate_value(v)

        result = loader.load_settings(overrides)
        expected = {**snapshot, **overrides}
        self.assertEqual(result, expected)
        self.assertIsNot(result, defaults)
        self.assertEqual(defaults, snapshot)

    def test_mutating_returned_dict_does_not_modify_defaults(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        result = loader.load_settings({})
        for k, v in snapshot.items():
            result[k] = _alternate_value(v)
        self.assertEqual(defaults, snapshot)

    def test_unknown_key_raises_value_error(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        unknown_key = "__unknown_setting_key__"
        while unknown_key in snapshot:
            unknown_key += "_"
        with self.assertRaises(ValueError):
            loader.load_settings({unknown_key: 1})
        self.assertEqual(defaults, snapshot)

    def test_unknown_key_with_valid_key_raises_value_error(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        unknown_key = "__unknown_setting_key__"
        while unknown_key in snapshot:
            unknown_key += "_"
        with self.assertRaises(ValueError):
            loader.load_settings({"port": 80, unknown_key: 1})
        self.assertEqual(defaults, snapshot)

    def test_wrong_type_for_each_setting_raises_value_error(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        for k, default_val in snapshot.items():
            for bad_val in _wrong_type_values(default_val):
                with self.subTest(key=k, bad_val=bad_val):
                    with self.assertRaises(ValueError):
                        loader.load_settings({k: bad_val})
                    self.assertEqual(defaults, snapshot)

    def test_bool_not_accepted_for_int_settings(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        int_keys = [k for k, v in snapshot.items() if type(v) is int]
        if not int_keys:
            int_keys = ["port", "workers"]
        for k in int_keys:
            for b in (True, False):
                with self.subTest(key=k, val=b):
                    with self.assertRaises(ValueError):
                        loader.load_settings({k: b})
                    self.assertEqual(defaults, snapshot)

    def test_port_valid_boundaries_and_values(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        for valid_port in (1, 80, 8080, 65535):
            with self.subTest(port=valid_port):
                result = loader.load_settings({"port": valid_port})
                self.assertEqual(result["port"], valid_port)
                self.assertEqual(defaults, snapshot)

    def test_port_out_of_range_raises_value_error(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        for invalid_port in (-100, -1, 0, 65536, 70000):
            with self.subTest(port=invalid_port):
                with self.assertRaises(ValueError):
                    loader.load_settings({"port": invalid_port})
                self.assertEqual(defaults, snapshot)

    def test_workers_valid_boundaries_and_values(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        for valid_workers in (1, 2, 16, 1024):
            with self.subTest(workers=valid_workers):
                result = loader.load_settings({"workers": valid_workers})
                self.assertEqual(result["workers"], valid_workers)
                self.assertEqual(defaults, snapshot)

    def test_workers_less_than_one_raises_value_error(self):
        defaults = _get_defaults()
        snapshot = dict(defaults)
        for invalid_workers in (-10, -1, 0):
            with self.subTest(workers=invalid_workers):
                with self.assertRaises(ValueError):
                    loader.load_settings({"workers": invalid_workers})
                self.assertEqual(defaults, snapshot)


if __name__ == "__main__":
    unittest.main()
