import unittest
import shapes
import ops


class TestMatrixOperations(unittest.TestCase):

    def test_shape_1x1(self):
        self.assertEqual(shapes.shape([[5]]), (1, 1))

    def test_shape_row_vector(self):
        self.assertEqual(shapes.shape([[1, 2, 3, 4]]), (1, 4))

    def test_shape_col_vector(self):
        self.assertEqual(shapes.shape([[1], [2], [3]]), (3, 1))

    def test_shape_rectangular(self):
        self.assertEqual(shapes.shape([[1, 2, 3], [4, 5, 6]]), (2, 3))

    def test_shape_empty_matrix_raises(self):
        with self.assertRaises(ValueError):
            shapes.shape([])

    def test_shape_single_empty_row_raises(self):
        with self.assertRaises(ValueError):
            shapes.shape([[]])

    def test_shape_later_empty_row_raises(self):
        with self.assertRaises(ValueError):
            shapes.shape([[1, 2], []])

    def test_shape_first_empty_row_then_non_empty_raises(self):
        with self.assertRaises(ValueError):
            shapes.shape([[], [1, 2]])

    def test_shape_ragged_rows_shorter_second_raises(self):
        with self.assertRaises(ValueError):
            shapes.shape([[1, 2, 3], [4, 5]])

    def test_shape_ragged_rows_longer_second_raises(self):
        with self.assertRaises(ValueError):
            shapes.shape([[1, 2], [3, 4, 5]])

    def test_shape_ragged_rows_later_row_differs_raises(self):
        with self.assertRaises(ValueError):
            shapes.shape([[1, 2], [3, 4], [5]])

    def test_matmul_1x1(self):
        self.assertEqual(ops.matmul([[3]], [[4]]), [[12]])

    def test_matmul_square(self):
        a = [[1, 2], [3, 4]]
        b = [[5, 6], [7, 8]]
        self.assertEqual(ops.matmul(a, b), [[19, 22], [43, 50]])

    def test_matmul_rectangular(self):
        a = [[1, 2, 3], [4, 5, 6]]
        b = [[7, 8], [9, 1], [2, 3]]
        self.assertEqual(ops.matmul(a, b), [[31, 19], [85, 55]])

    def test_matmul_row_by_col(self):
        a = [[1, 2, 3]]
        b = [[4], [5], [6]]
        self.assertEqual(ops.matmul(a, b), [[32]])

    def test_matmul_col_by_row(self):
        a = [[1], [2], [3]]
        b = [[4, 5]]
        self.assertEqual(ops.matmul(a, b), [[4, 5], [8, 10], [12, 15]])

