import unittest
import translit
import slug


class TestTranslitAndSlug(unittest.TestCase):
    def test_transliterate_umlauts_and_eszett(self):
        self.assertEqual(translit.transliterate("äöüß"), "aeoeuess")

    def test_transliterate_mixed_text(self):
        self.assertEqual(
            translit.transliterate("für größe und lärm"),
            "fuer groesse und laerm",
        )

    def test_transliterate_no_special_chars(self):
        self.assertEqual(translit.transliterate("hello 123"), "hello 123")

    def test_transliterate_empty(self):
        self.assertEqual(translit.transliterate(""), "")

    def test_make_slug_basic_and_lowercase(self):
        self.assertEqual(slug.make_slug("Hello World 123", 50), "hello-world-123")

    def test_make_slug_uppercase_umlauts_transliterated(self):
        self.assertEqual(slug.make_slug("Äpfel & Öl für Straße", 50), "aepfel-oel-fuer-strasse")

    def test_make_slug_non_ascii_runs_and_trim_hyphens(self):
        self.assertEqual(slug.make_slug("---Hello,   World!---", 50), "hello-world")

    def test_make_slug_non_ascii_non_translit_replaced(self):
        self.assertEqual(slug.make_slug("café résumé", 50), "caf-r-sum")

    def test_make_slug_max_len_exact(self):
        self.assertEqual(slug.make_slug("abcdef", 6), "abcdef")

    def test_make_slug_max_len_cut(self):
        self.assertEqual(slug.make_slug("abcdefgh", 5), "abcde")

    def test_make_slug_max_len_removes_trailing_hyphen_after_cut(self):
        self.assertEqual(slug.make_slug("abc def", 4), "abc")

    def test_make_slug_max_len_one(self):
        self.assertEqual(slug.make_slug("abc", 1), "a")

    def test_make_slug_translit_expands_before_cut(self):
        self.assertEqual(slug.make_slug("äb", 2), "ae")

    def test_make_slug_empty_input_raises(self):
        with self.assertRaises(ValueError):
            slug.make_slug("", 10)

    def test_make_slug_only_non_alnum_raises(self):
        with self.assertRaises(ValueError):
            slug.make_slug(" !@#--- ", 10)

    def test_make_slug_max_len_zero_raises(self):
        with self.assertRaises(ValueError):
            slug.make_slug("hello", 0)

    def test_make_slug_max_len_negative_raises(self):
        with self.assertRaises(ValueError):
            slug.make_slug("hello", -5)


if __name__ == "__main__":
    unittest.main()

