import unittest
import currency
import fmt


class TestFormatMoney(unittest.TestCase):
    def _extract_spec(self, entry):
        if isinstance(entry, dict):
            symbol = entry.get(
                "symbol", entry.get("sym", entry.get("sign", entry.get("prefix")))
            )
            decimals = entry.get(
                "decimals",
                entry.get(
                    "decimal_places",
                    entry.get(
                        "minor_units", entry.get("exponent", entry.get("digits"))
                    ),
                ),
            )
            if symbol is not None and decimals is not None:
                return symbol, decimals
            vals = list(entry.values())
            entry = vals
        if isinstance(entry, (tuple, list)) and len(entry) >= 2:
            if isinstance(entry[0], str) and isinstance(entry[1], int):
                return entry[0], entry[1]
            if isinstance(entry[1], str) and isinstance(entry[0], int):
                return entry[1], entry[0]
        symbol = None
        decimals = None
        for attr in ("symbol", "sym", "sign", "prefix"):
            if hasattr(entry, attr):
                val = getattr(entry, attr)
                if isinstance(val, str):
                    symbol = val
                    break
        for attr in (
            "decimals",
            "decimal_places",
            "minor_units",
            "exponent",
            "digits",
            "places",
        ):
            if hasattr(entry, attr):
                val = getattr(entry, attr)
                if isinstance(val, int):
                    decimals = val
                    break
        if symbol is None or decimals is None:
            for attr in dir(entry):
                if attr.startswith("_"):
                    continue
                val = getattr(entry, attr)
                if callable(val):
                    continue
                if isinstance(val, str) and symbol is None and val != getattr(entry, "code", None):
                    symbol = val
                elif isinstance(val, int) and not isinstance(val, bool) and decimals is None:
                    decimals = val
        return symbol, decimals

    def _get_currencies(self):
        raw = currency.CURRENCIES
        result = {}
        if isinstance(raw, dict):
            for code, entry in raw.items():
                sym, dec = self._extract_spec(entry)
                if sym is not None and dec is not None:
                    result[code] = (sym, dec)
        else:
            for entry in raw:
                code = getattr(entry, "code", None)
                if code is None and isinstance(entry, dict):
                    code = entry.get("code")
                if code is None and isinstance(entry, (tuple, list)) and len(entry) >= 3:
                    code = entry[0]
                    entry = entry[1:]
                sym, dec = self._extract_spec(entry)
                if code is not None and sym is not None and dec is not None:
                    result[code] = (sym, dec)
        return result

    def _expected(self, minor_units, sym, dec):
        neg = minor_units < 0
        val = abs(minor_units)
        factor = 10 ** dec
        whole = val // factor
        frac = val % factor
        whole_str = f"{whole:,}"
        if dec == 0:
            num_str = whole_str
        else:
            num_str = f"{whole_str}.{frac:0{dec}d}"
        prefix = "-" if neg else ""
        return f"{prefix}{sym}{num_str}"

    def test_zero_amount(self):
        for code, (sym, dec) in self._get_currencies().items():
            with self.subTest(code=code):
                self.assertEqual(
                    fmt.format_money(0, code),
                    self._expected(0, sym, dec),
                )

    def test_small_fractional_amounts(self):
        for code, (sym, dec) in self._get_currencies().items():
            for minor in (1, 5, 9, 10, 99):
                with self.subTest(code=code, minor=minor):
                    self.assertEqual(
                        fmt.format_money(minor, code),
                        self._expected(minor, sym, dec),
                    )

    def test_exact_unit_and_under_thousand(self):
        for code, (sym, dec) in self._get_currencies().items():
            factor = 10 ** dec
            for units in (1, 42, 999):
                minor = units * factor + (factor // 2 if dec > 0 else 0)
                with self.subTest(code=code, minor=minor):
                    self.assertEqual(
                        fmt.format_money(minor, code),
                        self._expected(minor, sym, dec),
                    )

    def test_thousands_grouping(self):
        for code, (sym, dec) in self._get_currencies().items():
            factor = 10 ** dec
            for units in (1000, 1234, 999999, 1000000, 1234567890):
                for rem in (0, factor - 1 if dec > 0 else 0):
                    minor = units * factor + rem
                    with self.subTest(code=code, minor=minor):
                        self.assertEqual(
                            fmt.format_money(minor, code),
                            self._expected(minor, sym, dec),
                        )

    def test_zero_decimal_currency_has_no_decimal_point(self):
        currencies = self._get_currencies()
        zero_dec = {k: v for k, v in currencies.items() if v[1] == 0}
        for code, (sym, dec) in zero_dec.items():
            for minor in (0, 1, 999, 1000, -1, -1234567):
                with self.subTest(code=code, minor=minor):
                    res = fmt.format_money(minor, code)
                    self.assertNotIn(".", res)
                    self.assertEqual(res, self._expected(minor, sym, dec))

    def test_negative_amounts_sign_before_symbol(self):
        for code, (sym, dec) in self._get_currencies().items():
            factor = 10 ** dec
            sample_minors = [-1, -factor, -(1234 * factor + (50 if dec >= 2 else 0)), -(1000000 * factor)]
            for minor in sample_minors:
                with self.subTest(code=code, minor=minor):
                    res = fmt.format_money(minor, code)
                    self.assertTrue(res.startswith(f"-{sym}"))
                    self.assertEqual(res, self._expected(minor, sym, dec))

    def test_unknown_currency_raises_value_error(self):
        known = set(self._get_currencies().keys())
        for bad_code in ("", "UNKNOWN", "ZZZ", "???", "invalid"):
            if bad_code not in known:
                with self.subTest(code=bad_code):
                    with self.assertRaises(ValueError):
                        fmt.format_money(100, bad_code)
        for code in list(known):
            if code.lower() not in known:
                with self.subTest(code=code.lower()):
                    with self.assertRaises(ValueError):
                        fmt.format_money(100, code.lower())


if __name__ == "__main__":
    unittest.main()
