import unittest
import currency
import fmt


def _extract_info(info):
    if isinstance(info, dict):
        sym = None
        dec = None
        for k, v in info.items():
            if isinstance(v, str) and (sym is None or "sym" in str(k).lower()):
                sym = v
            elif isinstance(v, int) and not isinstance(v, bool):
                dec = v
        return sym, dec
    if isinstance(info, (tuple, list)):
        sym = None
        dec = None
        for item in info:
            if isinstance(item, str) and sym is None:
                sym = item
            elif isinstance(item, int) and not isinstance(item, bool) and dec is None:
                dec = item
        return sym, dec
    try:
        d = vars(info)
        return _extract_info(d)
    except TypeError:
        pass
    sym = None
    dec = None
    for attr in ("symbol", "sym", "sign", "decimals", "decimal_places", "minor_units", "exponent", "digits", "precision", "scale"):
        try:
            val = info.__getattribute__(attr)
            if isinstance(val, str) and sym is None:
                sym = val
            elif isinstance(val, int) and not isinstance(val, bool) and dec is None:
                dec = val
        except AttributeError:
            pass
    return sym, dec


def _get_currencies():
    raw = currency.CURRENCIES
    result = {}
    if isinstance(raw, dict):
        for code, info in raw.items():
            sym, dec = _extract_info(info)
            if sym is not None and dec is not None:
                result[code] = (sym, dec)
    elif isinstance(raw, (list, tuple, set)):
        for item in raw:
            if isinstance(item, (tuple, list)) and len(item) == 3:
                code, a, b = item
                if isinstance(a, str) and isinstance(b, int):
                    result[code] = (a, b)
                elif isinstance(b, str) and isinstance(a, int):
                    result[code] = (b, a)
            else:
                try:
                    d = vars(item)
                    code = d.get("code") or d.get("iso_code") or d.get("id")
                    sym, dec = _extract_info(d)
                    if code and sym is not None and dec is not None:
                        result[code] = (sym, dec)
                except TypeError:
                    pass
    return result


def _expected_format(minor_units: int, symbol: str, decimals: int) -> str:
    sign = "-" if minor_units < 0 else ""
    abs_val = abs(minor_units)
    if decimals == 0:
        return f"{sign}{symbol}{abs_val:,}"
    factor = 10 ** decimals
    whole = abs_val // factor
    frac = abs_val % factor
    return f"{sign}{symbol}{whole:,}.{frac:0{decimals}d}"


class TestFormatMoney(unittest.TestCase):
    def setUp(self):
        self.currencies = _get_currencies()
        self.assertTrue(len(self.currencies) > 0, "currency.CURRENCIES must not be empty")

    def test_zero_amount_all_currencies(self):
        for code, (sym, dec) in self.currencies.items():
            expected = _expected_format(0, sym, dec)
            self.assertEqual(fmt.format_money(0, code), expected)

    def test_small_positive_amount(self):
        for code, (sym, dec) in self.currencies.items():
            for amount in (1, 5, 42, 99, 100, 105, 999):
                expected = _expected_format(amount, sym, dec)
                self.assertEqual(fmt.format_money(amount, code), expected)

    def test_thousands_grouping(self):
        for code, (sym, dec) in self.currencies.items():
            factor = 10 ** dec
            for whole in (1000, 1234, 999999, 1000000, 1234567890):
                amount = whole * factor + (50 if dec >= 2 else (5 if dec == 1 else 0))
                expected = _expected_format(amount, sym, dec)
                self.assertEqual(fmt.format_money(amount, code), expected)

    def test_no_thousands_separator_under_one_thousand(self):
        for code, (sym, dec) in self.currencies.items():
            factor = 10 ** dec
            amount = 999 * factor
            res = fmt.format_money(amount, code)
            self.assertEqual(res, _expected_format(amount, sym, dec))
            self.assertNotIn(",", res.replace(sym, ""))

    def test_zero_decimal_currencies_have_no_decimal_point(self):
        zero_dec = {k: v for k, v in self.currencies.items() if v[1] == 0}
        for code, (sym, dec) in zero_dec.items():
            for amount in (0, 1, 999, 1000, -1, -1234567):
                res = fmt.format_money(amount, code)
                self.assertEqual(res, _expected_format(amount, sym, dec))
                self.assertNotIn(".", res.replace(sym, ""))

    def test_negative_amounts_sign_before_symbol(self):
        for code, (sym, dec) in self.currencies.items():
            factor = 10 ** dec
            for amount in (-1, -50, -100, -(1234 * factor + (50 if dec >= 2 else 0)), -(1000000 * factor)):
                res = fmt.format_money(amount, code)
                expected = _expected_format(amount, sym, dec)
                self.assertEqual(res, expected)
                self.assertTrue(res.startswith("-" + sym))

    def test_docstring_example_if_usd_present(self):
        if "USD" in self.currencies and self.currencies["USD"] == ("$", 2):
            self.assertEqual(fmt.format_money(-123450, "USD"), "-$1,234.50")
            self.assertEqual(fmt.format_money(123450, "USD"), "$1,234.50")

    def test_unknown_currency_code_raises_value_error(self):
        for bad_code in ("UNKNOWN", "INVALID", "ZZZ", "", "usd", "123"):
            if bad_code not in self.currencies:
                with self.assertRaises(ValueError):
