import unittest
import words


class TestCapitalizeWords(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(words.capitalize_words(""), "")

    def test_single_lowercase_word(self):
        self.assertEqual(words.capitalize_words("hello"), "Hello")

    def test_single_letter_words(self):
        self.assertEqual(words.capitalize_words("a b c"), "A B C")

    def test_multiple_space_separated_words(self):
        self.assertEqual(
            words.capitalize_words("hello world from python"),
            "Hello World From Python",
        )

    def test_already_capitalized_words_unchanged(self):
        self.assertEqual(words.capitalize_words("Hello World"), "Hello World")

    def test_other_characters_case_preserved(self):
        self.assertEqual(
            words.capitalize_words("iPhone mcDonald ALLCAPS aBC"),
            "IPhone McDonald ALLCAPS ABC",
        )

    def test_non_space_separators_treated_as_same_word(self):
        self.assertEqual(
            words.capitalize_words("well-known state-of-the-art"),
            "Well-known State-of-the-art",
        )

    def test_apostrophe_within_word_unchanged(self):
        self.assertEqual(
            words.capitalize_words("don't won't"),
            "Don't Won't",
        )

    def test_multiple_spaces_preserved(self):
        self.assertEqual(
            words.capitalize_words("hello  world"),
            "Hello  World",
        )


if __name__ == "__main__":
    unittest.main()

