import unittest
import arith


class TestSafeDiv(unittest.TestCase):
    def test_positive_division_without_default(self):
        self.assertAlmostEqual(arith.safe_div(6.0, 3.0), 2.0)

    def test_positive_division_with_default(self):
        self.assertAlmostEqual(arith.safe_div(7.5, 2.5, default=0.0), 3.0)

    def test_negative_numerator(self):
        self.assertAlmostEqual(arith.safe_div(-10.0, 4.0, default=0.0), -2.5)

    def test_negative_denominator(self):
        self.assertAlmostEqual(arith.safe_div(10.0, -4.0, default=0.0), -2.5)

    def test_both_negative(self):
        self.assertAlmostEqual(arith.safe_div(-9.0, -3.0, default=0.0), 3.0)

    def test_zero_numerator_nonzero_denominator(self):
        self.assertAlmostEqual(arith.safe_div(0.0, 5.0, default=-1.0), 0.0)

    def test_fractional_division(self):
        self.assertAlmostEqual(arith.safe_div(1.0, 8.0), 0.125)

    def test_zero_denominator_returns_custom_default_float(self):
        self.assertEqual(arith.safe_div(5.0, 0.0, default=42.0), 42.0)

    def test_zero_denominator_returns_none_default(self):
        self.assertIsNone(arith.safe_div(5.0, 0.0, default=None))

    def test_zero_denominator_positional_default(self):
        self.assertEqual(arith.safe_div(5.0, 0.0, -99.5), -99.5)

    def test_negative_zero_denominator_returns_default(self):
        self.assertEqual(arith.safe_div(5.0, -0.0, default=12.5), 12.5)

    def test_both_zero_returns_default(self):
        self.assertEqual(arith.safe_div(0.0, 0.0, default=7.0), 7.0)


if __name__ == "__main__":
    unittest.main()

